action.command:
$file = ($input | ConvertFrom-Json).file
if (-not $file -or -not (Test-Path $file)) { exit 0 }
$content = Get-Content $file -Raw -ErrorAction SilentlyContinue
if (-not $content) { exit 0 }
$patterns = @(
  'ghp_[A-Za-z0-9]{36}',
  'github_pat_[A-Za-z0-9_]{82}',
  'sk-[A-Za-z0-9]{32,}',
  'AKIA[0-9A-Z]{16}',
  'AIza[0-9A-Za-z\-_]{35}',
  '-----BEGIN (RSA |EC |OPENSSH |DSA )?PRIVATE KEY',
  'xox[baprs]-[0-9A-Za-z\-]{10,}',
  '(?i)(password|passwd|secret|api[_-]?key|auth[_-]?token|access[_-]?token|private[_-]?key)\s*[:=]\s*["\x27][^"\x27]{8,}["\x27]'
)
foreach ($pattern in $patterns) {
  if ($content -match $pattern) {
    Write-Error "SECRET DETECTED in $file — move it to .env and reference it via import.meta.env instead."
    exit 2
  }
}
exit 0
